#!/bin/sh
# Creates <DB_BASE_NAME>_prod, _preview and _test, each owned by its own login role.
set -eu

# Stop with a clear message instead of creating databases named "_prod".
case "${DB_BASE_NAME:-}" in
  ''|*[!a-z0-9_]*|[0-9]*)
    echo "openship-init: DB_BASE_NAME is missing or invalid: '${DB_BASE_NAME:-}'" >&2
    exit 1
    ;;
esac

create_database() {
  env="$1"
  password="$2"
  db="${DB_BASE_NAME}_${env}"
  role="app_${env}"

  psql -v ON_ERROR_STOP=1 --username "$POSTGRES_USER" --dbname postgres \
    --set db="$db" --set role="$role" --set password="$password" <<'SQL'
CREATE ROLE :"role" WITH LOGIN NOSUPERUSER NOCREATEDB NOCREATEROLE CONNECTION LIMIT 20 PASSWORD :'password';
CREATE DATABASE :"db" OWNER :"role";
-- Only the owner may connect, so no environment can reach another one's database.
REVOKE ALL ON DATABASE :"db" FROM PUBLIC;
SQL

  # These extensions need the administrator; the migrations then find them in place.
  psql -v ON_ERROR_STOP=1 --username "$POSTGRES_USER" --dbname "$db" <<'SQL'
CREATE EXTENSION IF NOT EXISTS vector;
CREATE EXTENSION IF NOT EXISTS pg_textsearch;
CREATE EXTENSION IF NOT EXISTS unaccent;
SQL
}

create_database prod "$APP_PROD_PASSWORD"
create_database preview "$APP_PREVIEW_PASSWORD"
create_database test "$APP_TEST_PASSWORD"
